<template><main class="ccd-page achievements-page"><ConnectedDemoHeader icon="🏆" title="Achievements" subtitle="Recognise progress across community, streaming, games and real life"/><section class="achievements-layout"><div class="achievements-main"><section class="ccd-grid ccd-metrics"><ConnectedDemoMetric icon="🏆" label="Achievements" value="48" detail="Total created"/><ConnectedDemoMetric icon="🔒" label="Unlocked" :value="demo.achievement.unlocked?22:21" detail="43% of total"/><ConnectedDemoMetric icon="◷" label="In Progress" :value="demo.achievement.unlocked?8:9" detail="19% of total"/><ConnectedDemoMetric icon="✦" label="Rare Unlocks" value="3" detail="6% of total"/></section><section class="ccd-card featured"><div class="achievement-badge">♙<small>★</small></div><div><h2>Community Regular <span>EPIC</span></h2><p>Attend community events consistently.</p><label>PROGRESS <strong>{{demo.achievement.progress}} / 5</strong></label><div class="ccd-progress"><i :style="{width:demo.achievement.progress/5*100+'%'}"></i></div></div><div class="next-step"><small>NEXT STEP</small><b>{{demo.achievement.unlocked?'Achievement complete':'Attend Friday Game Night'}}</b><span>{{demo.event.attended?'Attendance verified':'0 / 1 attended'}}</span></div><div class="featured-reward"><small>REWARD</small><b>✦ 100 Points</b><span>⭐ Star Companion Badge</span></div><div class="overlay-setting"><small>ANNOUNCE ON OVERLAY</small><input v-model="demo.achievement.overlayEnabled" class="ccd-check" type="checkbox"><button class="ccd-button" @click="showOverlayPreview">◉ Preview</button></div></section><div class="ccd-tabs"><button v-for="cat in categories" :key="cat" class="ccd-tab" :class="{active:category===cat}" @click="category=cat">{{cat}}</button></div><section class="achievement-grid"><article v-for="item in filteredAchievements" :key="item.name" class="ccd-card" :class="{featuredCard:item.name==='Community Regular'}"><div class="mini-badge">{{item.icon}}</div><div><small :class="item.rarity.toLowerCase()">{{item.rarity}}</small><h3>{{item.name}}</h3><p>{{item.description}}</p></div><div class="ccd-progress"><i :style="{width:item.progress/item.goal*100+'%'}"></i></div><b>{{item.progress}} / {{item.goal}}</b><span>{{item.progress>=item.goal?'✓ UNLOCKED':item.locked?'🔒 LOCKED':'IN PROGRESS'}}</span></article></section><section class="achievement-bottom"><article class="ccd-card"><h2>Recent Unlocks</h2><ul class="ccd-list"><li v-for="item in recent" :key="item.name"><span>{{item.icon}}</span><div><b>{{item.name}}</b><small>Nova#1234 · {{item.when}}</small></div><strong class="ccd-cyan">+{{item.xp}} XP</strong></li></ul></article><article class="ccd-card journey"><h2>Achievement Journey</h2><div><span>🤝<small>First Connection</small></span><i></i><span>🎙<small>Positive Voice</small></span><i></i><span>🔥<small>Confidence Streak</small></span><i></i><span class="current">♙<small>Community Regular</small></span></div></article></section></div><aside class="achievement-rail"><section class="ccd-card builder"><h2>Achievement Builder　ⓘ</h2><label>1. Trigger<span>♙ <b>Attend Event</b><small>User joins an event</small></span></label><label>2. Progress Rule<span>▥ <b>Attend 5 Events</b><small>Increment by 1 per unique event</small></span></label><label>3. Reward<span>✦ <b>100 Points</b><small>Star Companion Badge</small></span></label><button class="ccd-button">＋ Add Reward</button><label>4. Visibility<select><option>🌐 Everyone</option></select></label><label class="toggle">5. Overlay Announcement<input v-model="demo.achievement.overlayEnabled" class="ccd-check" type="checkbox"></label><button class="ccd-button primary">Save Achievement (Demo)</button></section><section class="unlock-mini"><small>UNLOCK PREVIEW</small><div><span>🏆</span><b>Community Regular</b><p>Attend 5 community events.</p><strong>+100 XP　⭐</strong><small>Nova#1234</small></div><button class="ccd-button primary" @click="complete">✓ {{demo.achievement.unlocked?'Show unlock preview':'Complete final step'}}</button><p>{{demo.achievement.unlocked?'Achievement unlocked in this browser.':'Simulate attending Friday Game Night (5/5)'}}</p></section></aside></section><div v-if="demo.overlayPreviewOpen" class="ccd-overlay-modal" role="dialog" aria-modal="true" aria-label="Achievement unlock preview" @click.self="closeOverlayPreview"><section class="ccd-unlock"><div class="trophy">🏆</div><small>ACHIEVEMENT UNLOCKED!</small><h2>Community Regular</h2><p>Nova attended 5 community events.</p><strong>✦ +100 XP　⭐ Star Companion</strong><br><button class="ccd-button primary" @click="closeOverlayPreview">Close preview</button></section></div></main></template>
<script setup>import{computed,ref}from'vue';import ConnectedDemoHeader from'../../connected-demo/ConnectedDemoHeader.vue';import ConnectedDemoMetric from'../../connected-demo/ConnectedDemoMetric.vue';import{connectedDemo as demo,attendFridayGameNight,closeOverlayPreview,showOverlayPreview,unlockCommunityRegular}from'../../connected-demo/connectedDemoState.js';import'../../connected-demo/connectedDemo.css';const category=ref('Community');const categories=['All','Community','Streaming','Events','Games','Social Confidence','IRL'];const base=[['🤝','First Connection','Introduce yourself in our community.','Common','Community',1,1],['♙','Community Regular','Attend 5 community events.','Epic','Community',0,5],['🎙','Positive Voice','Receive 10 positive reactions.','Rare','Social Confidence',7,10],['🎟','Event Explorer','Attend 3 different events.','Common','Events',2,3],['💜','Creator Supporter','Support 5 creators in the community.','Epic','Community',3,5],['🔥','Confidence Streak','Join voice chat 5 days in a row.','Rare','Social Confidence',3,5],['♙','Team Player','Win 10 matches with your squad.','Rare','Games',6,10],['🏙','Real-World Win','Attend a Project Respawn IRL meet-up.','Epic','IRL',0,1]].map(([icon,name,description,rarity,cat,progress,goal])=>({icon,name,description,rarity,cat,progress,goal,locked:name==='Real-World Win'}));const filteredAchievements=computed(()=>base.map(x=>x.name==='Community Regular'?{...x,progress:demo.achievement.progress}:{...x}).filter(x=>category.value==='All'||x.cat===category.value));const recent=[{icon:'♙',name:'Community Regular',when:'Preview',xp:100},{icon:'🤝',name:'First Connection',when:'2 days ago',xp:25},{icon:'🎙',name:'Positive Voice',when:'5 days ago',xp:75}];function complete(){attendFridayGameNight();unlockCommunityRegular();showOverlayPreview()}</script>
<style scoped>.achievements-layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:14px}.featured{display:grid;grid-template-columns:110px 1.4fr 1fr 1fr 150px;align-items:center;gap:16px;margin-bottom:12px;border-color:#7d43cc}.achievement-badge{display:grid;width:88px;height:88px;place-items:center;border:3px solid #537fff;clip-path:polygon(50% 0,93% 25%,93% 75%,50% 100%,7% 75%,7% 25%);background:#172d6c;font-size:38px}.achievement-badge small{font-size:12px}.featured h2{font-size:22px}.featured h2 span{padding:3px 7px;border:1px solid #8b3acb;border-radius:5px;color:#d677ff;font-size:11px}.featured label{display:flex;justify-content:space-between}.next-step,.featured-reward,.overlay-setting{display:grid;gap:7px;padding-left:15px;border-left:1px solid #2c3c55}.next-step small,.featured-reward small,.overlay-setting small{color:#9ba8bb}.overlay-setting .ccd-check{justify-self:end}.achievement-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.achievement-grid article{display:grid;grid-template-columns:60px 1fr auto;gap:8px;min-height:158px}.achievement-grid article.featuredCard{border-color:#4d94ff}.mini-badge{display:grid;width:58px;height:58px;place-items:center;clip-path:polygon(50% 0,93% 25%,93% 75%,50% 100%,7% 75%,7% 25%);background:#15385c;font-size:28px}.achievement-grid h3{margin:3px 0}.achievement-grid p{margin:0;color:#aab6c7;font-size:12px}.achievement-grid .ccd-progress{grid-column:1/3}.achievement-grid>article>b{font-size:12px}.achievement-grid>article>span{grid-column:1/-1;justify-self:center;padding:4px 18px;border:1px solid #175787;border-radius:5px;color:#5ccaff;font-size:11px}.common{color:#b8c2d1}.rare{color:#24baf0}.epic{color:#d46cff}.achievement-bottom{display:grid;grid-template-columns:.8fr 1.4fr;gap:10px;margin-top:12px}.journey>div{display:flex;align-items:center;justify-content:space-around;margin-top:25px}.journey span{display:grid;place-items:center;font-size:32px}.journey span.current{filter:drop-shadow(0 0 10px #bd55ff)}.journey small{display:block;font-size:11px}.journey i{width:12%;height:3px;background:#52617b}.achievement-rail{display:grid;align-content:start;gap:14px}.builder label{display:grid;gap:6px;margin:14px 0;font-weight:700}.builder label>span{display:grid;grid-template-columns:35px 1fr;padding:11px;border:1px solid #2e425e;border-radius:7px;font-weight:400}.builder label small{grid-column:2;color:#9eacc0}.builder select{min-height:38px;padding:7px;border:1px solid #304661;border-radius:6px;background:#09162a;color:#fff}.builder .toggle{display:flex;justify-content:space-between}.builder>.ccd-button{width:100%;margin-top:7px}.unlock-mini{text-align:center}.unlock-mini>small{color:#aab6ca}.unlock-mini>div{display:grid;margin:20px 10px;padding:24px;border:2px solid #6950e8;border-radius:10px;background:radial-gradient(circle,#25125a,#09162b);box-shadow:0 0 35px rgba(114,74,220,.35)}.unlock-mini>div>span{font-size:48px}.unlock-mini>div>b{font-size:20px}.unlock-mini>div>strong{color:#53e2ee}.unlock-mini>.ccd-button{width:100%}.unlock-mini>p{color:#95a3b7;font-size:11px}@media(max-width:1450px){.achievements-layout{grid-template-columns:1fr}.achievement-rail{grid-template-columns:1fr 1fr}.achievement-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:1000px){.featured{grid-template-columns:90px 1fr 1fr}.featured-reward,.overlay-setting{grid-column:auto}.achievement-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.featured,.achievement-grid,.achievement-bottom,.achievement-rail{grid-template-columns:1fr}.achievement-badge{margin:auto}.next-step,.featured-reward,.overlay-setting{border-left:0;border-top:1px solid #2c3c55;padding:10px 0}}</style>
